<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';
import {metadata} from '../services/metadata';
import {collectionsChanged} from '../stores/collections';
import {refreshAssets} from '../stores/assets';
type Target={assetId:string;before:unknown;after:unknown;conflicts:string[]};
type Preview={items:Target[];planToken:string;next_cursor:string|null;targetCount:number;changedCount:number;conflictCount:number};
const content=ref(''),format=ref('json'),rebase=ref(false),approved=ref(false),busy=ref(false),message=ref(''),preview=ref<Preview>(),rows=ref<Target[]>([]);let generation=0;
watch([content,format,rebase],()=>{generation++;preview.value=undefined;rows.value=[];approved.value=false;message.value='';});onBeforeUnmount(()=>generation++);
async function readFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const token=++generation;preview.value=undefined;rows.value=[];approved.value=false;if(file.size>6000){message.value='문서는 UTF-8 6000바이트 이하여야 합니다.';return;}try{const text=await file.text();if(token===generation)content.value=text;}catch{message.value='문서를 읽지 못했습니다.';}}
function request(){return {content:content.value,format:format.value,use_current_versions:rebase.value};}
async function review(more=false){if(busy.value||!content.value)return;if(new TextEncoder().encode(content.value).length>6000){message.value='문서는 UTF-8 6000바이트 이하여야 합니다.';return;}const token=generation;busy.value=true;message.value='';try{const result=await metadata<Preview>('exchange.preview',{...request(),after_id:more?preview.value?.next_cursor:null,plan_token:more?preview.value?.planToken:null});if(token!==generation)return;preview.value=result;rows.value=more?[...rows.value,...result.items]:result.items;}catch{if(token===generation){preview.value=undefined;rows.value=[];approved.value=false;message.value='검토 실패: 스키마·실제 ID/참조·버전·크기·관계 순환을 확인하세요.';}}finally{busy.value=false;}}
async function apply(){if(busy.value||!approved.value||!preview.value||preview.value.next_cursor||preview.value.conflictCount)return;const token=generation;busy.value=true;try{const result=await metadata<{updated:number;unchanged:number}>('exchange.apply',{...request(),plan_token:preview.value.planToken,confirmed:true});if(token!==generation)return;preview.value=undefined;approved.value=false;rows.value=[];message.value=`가져오기 ${result.updated}개 저장 · ${result.unchanged}개 변경 없음`;collectionsChanged();await refreshAssets();}catch{if(token===generation){preview.value=undefined;approved.value=false;message.value='가져오기 실패: 전체 변경을 취소했습니다. 다시 검토하세요.';}}finally{busy.value=false;}}
</script>
<template><details class="metadata-import"><summary>JSON/CSV 메타데이터 가져오기</summary><p>이 앱의 metadata-exchange.v1 공개 문서만 지원합니다. 등록된 실제 에셋/참조만 변경하며 새 폴더·모델·분석·URL 요청을 만들지 않습니다. 문서최대6000 UTF-8바이트·20개 에셋입니다.</p><label>문서 파일<input type="file" accept=".json,.csv" :disabled="busy" @change="readFile" /></label><label>문서 형식<select v-model="format" :disabled="busy"><option value="json">JSON</option><option value="csv">CSV</option></select></label><label>문서 내용<textarea v-model="content" :disabled="busy" rows="6" /></label><label><input v-model="rebase" type="checkbox" :disabled="busy" />파일 버전과 달라도 현재 값 기준으로 새로 비교 검토합니다.</label><button type="button" :disabled="busy||!content" @click="review()">가져오기 검토</button><template v-if="preview"><p>대상 {{preview.targetCount}}개 · 변경 {{preview.changedCount}}개 · 충돌 {{preview.conflictCount}}개</p><ol><li v-for="row in rows" :key="row.assetId"><p>{{row.assetId}} · {{row.conflicts.join(', ')||'검토 가능'}}</p><p>이전 {{JSON.stringify(row.before)}}</p><p>이후 {{JSON.stringify(row.after)}}</p></li></ol><button v-if="preview.next_cursor" type="button" :disabled="busy" @click="review(true)">다음 가져오기 검토</button><label><input v-model="approved" type="checkbox" :disabled="busy||!!preview.next_cursor||!!preview.conflictCount" />모든 전후 값을 확인했고 원자 적용을 승인합니다.</label><button type="button" :disabled="busy||!approved||!!preview.next_cursor||!!preview.conflictCount||!preview.changedCount" @click="apply">검토한 가져오기 적용</button></template><p v-if="message" role="status">{{message}}</p></details></template>
